-- create tables
CREATE TABLE IF NOT EXISTS club(id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, place TEXT);
CREATE TABLE IF NOT EXISTS participants (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, club_id INTEGER, level TEXT, born INTEGER, FOREIGN KEY (club_id) REFERENCES club(id));
CREATE TABLE IF NOT EXISTS tournament (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, place TEXT NOT NULL, tdate TEXT NOT NULL, referre TEXT NOT NULL, secretary TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS category (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS competition (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, gender INTEGER NOT NULL, age TEXT, level TEXT, category_id INTEGER, tournament_id INTEGER, FOREIGN KEY (category_id) REFERENCES category(id), FOREIGN KEY (tournament_id) REFERENCES tournament(id));
CREATE TABLE IF NOT EXISTS competition_participants (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, pos INTEGER, competition_id INTEGER NOT NULL, participant_id INTEGER, FOREIGN KEY (competition_id) REFERENCES competition (idx), FOREIGN KEY (participant_id) REFERENCES perticipants(id));и